import datetime

from detectron2.utils import comm

class EventStorage:
    """
    A storage class that stores events during training.
    """

    def __init__(self):
        self._events = []

    def put_event(self, event):
        """
        Add an event to the current iteration's events.
        """
        if not isinstance(event, dict):
            event = {"event": event}
        else:
            event.setdefault("iteration", comm.get_rank())
        self._events.append(event)

    def get_events(self, filter_func=None):
        """
        Get all events collected so far. If `filter_func` is provided,
        only return events for which `filter_func(event)` is True.
        """
        if filter_func is None:
            return self._events
        else:
            return [x for x in self._events if filter_func(x)]

    @property
    def num_events(self):
        return len(self._events)
